insert into leads (lead_id, company_name, industry, csr_focus_area, city, state, geo_scope, poc_name, poc_designation, poc_email, poc_phone, poc_linkedin, contact_source, source_type, source_name, post_link, signal_type, budget_inr_cr, budget_basis, posted_at, posted_time_precision, implementation_partner, beneficiaries, summary, why_now, priority_score, probability_of_conversion_pct, tier, recommended_action, pipeline_stage, owner, is_synthetic, verified_at, proven_funder, score_signal, score_recency, score_sector_fit, score_geo_fit, score_budget_fit, flags, hot_gate_fails, programme_states, extraction_confidence, scored_at) values
  ('LIVE-008', 'BASF India Ltd', 'Chemicals', 'Education', 'Nashik', 'Maharashtra', 'state', 'Bahram Vakil', 'Chairman, CSR Committee (Independent Director)', null, null, null, 'CSR committee disclosure', 'annual_report', 'India CSR (annual report coverage)', 'https://indiacsr.in/basf-india-csr-spending-report-2026/', 'unspent_csr', 8.86, 'stated', '2026-09-15T00:00:00+05:30', 'date', 'Not named', 'Gadchiroli livelihood programme reached 5,657 people', 'FY26 CSR spend Rs 15.61 Cr against Rs 12.93 Cr obligation. Education and rural infrastructure was the largest head at Rs 7.66 Cr. Rs 8.86 Cr moved to the Unspent CSR Account on 8 Apr 2026 for ongoing projects. Maharashtra sites include Nashik and Gadchiroli.', 'The Rs 8.86 Cr is tied to ongoing projects that must finish within 3 years, and no partners are named. Ask whether an education project in Maharashtra needs delivery capacity. Strongest real lead in this snapshot.', 70, 20.6, 'warm', 'Email plus LinkedIn connect this week. Call slot next week if they reply.', 'new', 'Ananya', false, '2026-10-12', false, 20, 15, 10, 15, 10, '{}', '{}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-001', 'Zeta', 'Banking technology', 'Youth Employment', 'Hyderabad', 'Telangana', 'other', 'Sivaram Kowta', 'President, Zeta India', null, null, null, 'Named in article', 'news', 'Newspatrolling', 'https://newspatrolling.com/zeta-inaugurates-hyderabad-skilling-centre-to-help-underprivileged-youth-prepare-for-employment-and-entrepreneurship/', 'new_initiative', null, 'unknown', '2026-10-12T00:00:00+05:30', 'date', 'Head Held High Foundation', '2 batches of 60 youth per centre, 3 month programme', 'Zeta CARES inaugurated a youth skilling centre in Hyderabad on 10 Oct covering functional, digital and workplace skills. Bengaluru and Mumbai centres are already running, with formal launches planned in coming months.', 'Mumbai centre is live, so Zeta funds youth skilling in Maharashtra. Partner already in place: pitch a Pune centre, not this one.', 60, 15.7, 'warm', 'Email plus LinkedIn connect this week. Call slot next week if they reply.', 'new', 'Ananya', false, '2026-10-12', true, 22, 20, 15, 15, 3, '{"partner_already_selected","programme_in_home_state"}', '{"partner_already_selected"}', '{"Telangana","Karnataka","Maharashtra"}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-002', 'Motorola Mobility', 'Consumer electronics', 'Education', 'India', null, 'pan_india', 'Pratima Harite', 'Head, Asia Pacific, Corporate Citizenship', null, null, null, 'Interviewed in article', 'news', 'The CSR Universe', 'https://thecsruniverse.com/articles/beyond-digital-access-how-motorola-mobility-is-bringing-stem-and-ai-learning-to-government-schools', 'event_or_vlog', null, 'unknown', '2026-10-12T00:00:00+05:30', 'date', null, 'Thousands of government school students', 'Interview on STEMSpark, which sets up AI and robotics labs in government schools. Says scale will need long term partnerships across government, civil society and the private sector. No NGO partner named.', 'Open statement that partners are needed, no partner named. Low effort LinkedIn note referencing the interview.', 49, 11.1, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 6, 20, 10, 10, 3, '{}', '{}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-005', 'BT Group', 'Telecom', 'Digital Literacy', 'Gurugram', 'Haryana', 'pan_india', 'Ian McBride', 'Head, Responsible Business and Social Impact, India', null, null, null, 'Named in article (chief guest)', 'news', 'The CSR Universe', 'https://thecsruniverse.com/articles/etasha-society-launches-digisaksham-to-promote-online-safety', 'new_initiative', null, 'unknown', '2026-10-09T00:00:00+05:30', 'date', 'ETASHA Society (with British Asian Trust)', 'Target 20,000 young people', 'ETASHA Society launched DigiSaksham, a free online platform on digital literacy and online safety for underserved youth, supported by BT Group and British Asian Trust.', 'National digital literacy funder. Partner chosen for this platform; ask about offline delivery partners in Maharashtra.', 48, 10.8, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 15, 13, 10, 3, '{"partner_already_selected"}', '{"partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-003', 'Birla Cable Ltd', 'Cables', 'Skill Development', 'Rewa', 'Madhya Pradesh', 'other', 'Harsh V. Lodha', 'Chairman, CSR Committee', null, null, null, 'CSR committee disclosure', 'annual_report', 'India CSR (annual report coverage)', 'https://indiacsr.in/birla-cable-csr-spending-fy-2025-26-rewa/', 'annual_report_mention', 0.28, 'stated', '2026-10-11T00:00:00+05:30', 'date', 'M.P. Birla Foundation Industrial Training Centre', 'Not stated', 'FY26 CSR spend of Rs 49.95 lakh against a Rs 49.94 lakh obligation. About 55 percent (Rs 27.64 lakh) went to ITI infrastructure in Rewa. No unspent amount.', 'Small ticket, outside footprint, in house ITI. Track only.', 46, 10, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 6, 20, 15, 0, 5, '{}', '{"outside_footprint"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-012', 'Envalior India', 'Engineering materials', 'Skill Development', 'Pimpri Chinchwad', 'Maharashtra', 'city', 'Nileshkumar Kukalyekar', 'Business Director, South Asia, Middle East and Africa', null, null, null, 'Named in article', 'news', 'Autocar Professional', 'https://www.autocarpro.in/news/envalior-opens-ev-skilling-centre-at-mm-polytechnic-in-pune-under-csr-initiative-133966', 'new_initiative', null, 'unknown', '2026-08-07T00:00:00+05:30', 'date', 'BroadArks Foundation', 'About 250 ITI and polytechnic learners a year', 'EV Technology Centre of Excellence at MM Polytechnic, Pimpri Chinchwad, with NSDC certified EV service and diagnostics courses.', 'Proven funder of skilling in Pune. Targets ITI students, not dropouts: pitch a dropout to ITI bridge feeding their centre.', 45, 9.7, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', true, 22, 0, 15, 20, 3, '{"partner_already_selected"}', '{"too_old","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-013', 'Sona Comstar', 'Auto components', 'Skill Development', 'Chakan, Pune', 'Maharashtra', 'city', 'Priya Kapur', 'Non-Executive Director and Chairperson, CSR Committee', null, null, null, 'Named in article', 'news', 'India CSR', 'https://indiacsr.in/csr-sona-comstar-tata-strive-open-skill-centre-in-chakan/', 'new_initiative', null, 'unknown', '2026-08-01T00:00:00+05:30', 'date', 'Tata STRIVE', '220 unemployed youth in FY 2026-27 (CNC, electrician, BFSI)', 'Skill development centre in Chakan training unemployed youth in CNC operations, electrician and BFSI trades.', 'Exact programme fit in Pune, partner in place for FY27. Pitch for FY28 before their April action plan.', 45, 9.7, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', true, 22, 0, 15, 20, 3, '{"partner_already_selected"}', '{"too_old","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-007', 'Nayara Energy', 'Oil and gas', 'Education', 'Mumbai', 'Maharashtra', 'state', 'Prasad K. Panicker', 'Executive Chairman', null, null, null, 'Named in article', 'news', 'India CSR', 'https://indiacsr.in/nayara-energy-supports-90-iim-mumbai-students-with-scholarships/', 'new_initiative', 4.5, 'stated', '2026-09-15T00:00:00+05:30', 'date', 'IIM Mumbai (direct institutional grant)', '90 MBA students', 'Rs 4.5 Cr in scholarships for 90 IIM Mumbai MBA students, part of a Rs 17.5 Cr two year partnership.', 'Higher education, not dropout skilling. Weak fit despite the Mumbai base.', 44, 9.4, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', true, 22, 2, 10, 15, 10, '{"partner_already_selected"}', '{"too_old","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-004', 'Genpact', 'Professional services', 'Youth Employment', 'Kolkata', 'West Bengal', 'other', 'Sutanuka Ghosh', 'Lead, CSR', null, null, null, 'Named in press release', 'press_release', 'ANI (press release)', 'https://aninews.in/news/business/genpact-supported-skill-bridge-project-implemented-by-reacha-with-certification-by-tata-strive-for-youth-employability-in-kolkata-west-bengal20261009154559', 'new_initiative', null, 'unknown', '2026-10-09T15:45:00+05:30', 'time', 'REACHA (certification by Tata STRIVE)', '200 youth, 10th/12th pass, 18+', 'Genpact Skill BRIDGE trains 200 Kolkata youth in General Duty Assistant (elder care) and housekeeping, with employability support.', 'Partner selected and outside footprint. Useful as a model: an IT services firm funding entry level jobs for school pass youth.', 40, 8.1, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 15, 15, 0, 3, '{"partner_already_selected"}', '{"outside_footprint","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-014', 'Yardi Software India Pvt Ltd', 'Software', 'Youth Employment', 'Chhatrapati Sambhajinagar', 'Maharashtra', 'state', 'Bharati Kotwal', 'CSR Head', null, null, null, 'Named in article', 'news', 'The CSR Universe', 'https://thecsruniverse.com/articles/byst-yardi-launch-entrepreneurship-programme-for-youth-in-maharashtra', 'new_initiative', null, 'unknown', '2026-05-20T00:00:00+05:30', 'date', 'Bharatiya Yuva Shakti Trust (BYST)', '100 youth entrepreneurs mentored; 6,400 reached', 'Young Grampreneur programme for rural youth entrepreneurship in Chhatrapati Sambhajinagar.', 'Software firm funding youth livelihoods in Maharashtra. Old signal: nurture for next cycle.', 40, 8.1, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', true, 22, 0, 15, 15, 3, '{"partner_already_selected"}', '{"too_old","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-015', 'VFS Global Foundation', 'Visa services', 'Youth Employment', 'Mumbai', 'Maharashtra', 'state', 'Nirbhik Goel', 'Chief Human Resources Officer, VFS Global', null, null, null, 'Named in article', 'news', 'The CSR Universe', 'https://thecsruniverse.com/articles/vfs-global-foundation-opens-skills-training-centre-in-mumbai', 'new_initiative', null, 'unknown', '2026-05-15T00:00:00+05:30', 'date', 'VFS Global Academy (in house)', 'First batch of 30', 'First Mumbai skills centre (sixth in India) running a one month retail associate certificate for underserved youth.', 'Runs training in house, so a partner role is unlikely. Possible mobilisation partner for trainees.', 40, 8.1, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 0, 15, 15, 3, '{"implemented_in_house"}', '{"too_old","implemented_in_house"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-006', 'Castrol India Ltd', 'Lubricants', 'Youth Employment', 'Kolkata', 'West Bengal', 'other', 'Saugata Basuray', 'Managing Director', null, null, null, 'Quoted in article', 'news', 'India CSR', 'https://indiacsr.in/castrol-india-csr-skilling-centre-kolkata-ujjwal-kal/', 'new_initiative', null, 'unknown', '2026-10-01T00:00:00+05:30', 'date', 'Smile Foundation', 'Youth 18 to 28; Ujjwal Kal reached about 5,000 people in 2025', 'First Ujjwal Kal skilling centre opened in Kolkata with Smile Foundation. Programme mostly serves young women.', 'Labelled the first centre, which implies more may follow, but no expansion plans are stated. Ask, do not assume.', 32, 5.9, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 7, 15, 0, 3, '{"partner_already_selected"}', '{"outside_footprint","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-010', 'NEEPCO', 'Power (PSU)', 'Skill Development', 'North East (7 power station sites)', 'Assam', 'other', null, null, null, null, null, 'Not published in source. Find via company CSR policy page or annual report.', 'news', 'PSU Connect', 'https://www.psuconnect.in/corporate-social-responsibility/neepco-to-train-141-unemployed-youths-under-csr-skill-development-programme', 'new_initiative', null, 'unknown', '2026-08-18T00:00:00+05:30', 'date', 'CIPET-CSTS Guwahati', '141 unemployed youth', 'Placement linked polymer science training for 141 youth near NEEPCO power stations. Agreement signed 17 Aug.', 'PSUs default to government training bodies like CIPET. Outside footprint. Track only.', 25, 4.4, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 0, 15, 0, 3, '{"partner_already_selected"}', '{"too_old","outside_footprint","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-011', 'Tata Consulting Engineers', 'Engineering services', 'Skill Development', 'New Delhi', 'Delhi', 'other', 'Nidhi Mehandiratta', 'CHRO and CSR Head', null, null, null, 'Named in article', 'news', 'Skill Reporter', 'https://www.skillreporter.com/news/ssc/cgssc/cgssc-tata-tce-csr-skilling-utkarsh-project/', 'new_initiative', null, 'unknown', '2026-08-07T00:00:00+05:30', 'date', 'Capital Goods and Strategic Skill Council (CGSSC)', 'Technical students in Delhi NCR and Jamshedpur; about 600 completed', 'Project UTKARSH, a CSR skilling programme for EPC sector roles, launched at Don Bosco Technical Institute, Okhla.', 'Outside footprint, partner chosen. Track only.', 25, 4.4, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 0, 15, 0, 3, '{"partner_already_selected"}', '{"too_old","outside_footprint","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30'),
  ('LIVE-009', 'Supreme Industries Ltd', 'Plastics', 'Education', 'Rajasthan (rural)', 'Rajasthan', 'other', null, null, null, null, null, 'Not published in source. Find via company CSR policy page or annual report.', 'news', 'India CSR', 'https://indiacsr.in/ai-powered-classrooms-rural-rajasthan-supreme-industries-cybernetyx/', 'new_initiative', null, 'unknown', '2026-09-11T00:00:00+05:30', 'date', 'Cybernetyx', 'Not stated', 'AI powered classrooms with teacher training and digital content in rural Rajasthan schools.', 'Outside footprint, partner chosen. Track only.', 20, 3.5, 'cold', 'No call. Add to nurture list and re-score if a new signal appears.', 'new', 'Ananya', false, '2026-10-12', false, 22, 0, 10, 0, 3, '{"partner_already_selected"}', '{"too_old","outside_footprint","partner_already_selected"}', '{}', 'high', '2026-10-12T18:00:00+05:30')
